{"args": {"content": "def lcm_val(a, b):
    if a == 0 or b == 0:
        return 0
    else:
        # Calcula o máximo divisor comum (MDC)
        while b != 0:
            temp = b
            b = a % b
            a = temp
        # Calcula o mínimo múltiplo comum (MMC)
        return abs(a * b) // a", "path": "src/pure_ops.py"}, "tool": "write_file"}

