{"args": {"content": "class MinTracker:
    def __init__(self):
        self.stack = []
        self.min_stack = []

    def push(self, x):
        if not self.min_stack or x <= self.min_stack[-1]:
            self.min_stack.append(x)
        self.stack.append(x)

    def pop(self):
        if not self.stack:
            return None
        popped = self.stack.pop()
        if popped == self.min_stack[-1]:
            self.min_stack.pop()
        return popped

    def get_min(self):
        return self.min_stack[-1] if self.min_stack else None", "path": "src/structures.py"}, "tool": "write_file"}

